  if(Core.utf(text).length>32*1024*1024)throw new Exception("Event pack exceeds 32 MB.");
  JSONObject before=catalogue.synced;
  try{int count=catalogue.merge(new JSONObject(text));save();notice="Imported "+count+" new titles from event pack (Testing). Existing mappings retained.";}
  catch(Exception e){catalogue.synced=before;throw new Exception("Could not import event pack. Choose a JSON pack containing templates and mappings. Existing data retained.");}
