 void importQueues(String text)throws Exception{
  if(queueGate.busy())throw new Exception("Pause Auto Unlock before importing queues.");String owner=auth().getString("xuid");JSONObject value=QueueTransfer.parse(text,owner),staged=new JSONObject();JSONArray transfers=value.getJSONArray("games");
  for(int g=0;g<transfers.length();g++){JSONObject transfer=transfers.getJSONObject(g);String title=transfer.getString("titleId");for(int i=0;i<queue.length();i++)if(queue.getJSONObject(i).getJSONObject("game").getString("titleId").equals(title))throw new Exception("This transfer includes a game in your active queue. Load a different saved game before importing; current progress was retained.");JSONObject game=lookup(title);JSONArray fresh=rows(game,owner),source=transfer.getJSONArray("items"),items=new JSONArray();for(int i=0;i<source.length();i++){JSONObject old=source.getJSONObject(i),row=selectRow(fresh,old.getString("achievementId"));if(!row.getString("name").equalsIgnoreCase(old.getString("name")))throw new Exception("Achievement name or edition differs; import cancelled.");JSONObject item=new JSONObject().put("game",game).put("achievementId",row.getString("id")).put("name",row.getString("name")).put("description",row.optString("description",row.optString("lockedDescription"))).put("delay",old.getDouble("delaySeconds")).put("status",QueueTransfer.importedStatus(old.getString("status"),unlocked(row)));if(!old.isNull("remainingDelaySeconds"))item.put("remainingDelay",old.getDouble("remainingDelaySeconds"));items.put(item);}QueueLibrary.capture(staged,new JSONArray(),items);}
  Core.sameOwner(owner,auth().getString("xuid"));for(Iterator<String> it=staged.keys();it.hasNext();){String id=it.next();savedQueues.put(id,staged.get(id));}save();notice="Imported "+transfers.length()+" saved queues. Load and review before starting.";
 }
 void startSpoof(String title)throws Exception{
  if(spoofGate.busy()||!foreground)throw new Exception("Wait for the previous spoof to finish, then start while the app is open.");
  Core.numeric(title);JSONObject initial=auth();String owner=initial.getString("xuid");SessionService.ensure(this);long generation=spoofGate.start();
  spoofRunning=true;spoofTitle=title;spoofStatus="Sending heartbeat…";keepAwake();
  spoofJob=sessions.submit(()->{if(!spoofGate.begin(generation))return;JSONObject cleanup=initial;boolean sent=false;try{
   while(spoofGate.running(generation)&&sessionAllowed()){JSONObject active=auth();Core.sameOwner(owner,active.getString("xuid"));if(Thread.currentThread().isInterrupted())throw new InterruptedException();heartbeat(active,title);cleanup=active;sent=true;if(spoofStarted==0)spoofStarted=System.currentTimeMillis();spoofStatus="Heartbeat accepted";push();Thread.sleep(240000);}
  }catch(InterruptedException ignored){}catch(Exception e){spoofStatus=safe(e);if(prefs.optBoolean("stopOnSpoofFailure",true))pause();if(prefs.optBoolean("notifySpoofFailure",true))notifyUser("Title spoofing stopped",spoofStatus);
  }finally{Thread.interrupted();try{if(!preview&&sent)Net.presence(cleanup,null);}catch(Exception ignored){}spoofRunning=false;spoofStarted=0;spoofGate.finish(generation);keepAwake();push();}});
 }
 void heartbeat(JSONObject active,String title)throws Exception{for(int attempt=0;;attempt++){try{Net.presence(active,title);return;}catch(Exception e){if(attempt>=2||!QueuePolicy.transientFailure(e))throw e;Thread.sleep(2000L*(attempt+1));}}}
 void stopSpoof(){spoofGate.pause();spoofRunning=false;spoofStarted=0;if(spoofJob!=null)spoofJob.cancel(true);spoofStatus="Stopped";keepAwake();push();}
 void notifyUser(String title,String message){main.post(()->{NotificationManager n=getSystemService(NotificationManager.class);n.createNotificationChannel(new NotificationChannel("labs","Achievement Labs",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);try{n.notify((int)(System.currentTimeMillis()%Integer.MAX_VALUE),new Notification.Builder(this,"labs").setSmallIcon(android.R.drawable.star_on).setContentTitle(title).setContentText(message).setContentIntent(open).setAutoCancel(true).build());}catch(SecurityException ignored){}});}
 Object handle(String action,JSONObject p)throws Exception{
  if(action.equals("rendered")&&preview){try(FileOutputStream marker=openFileOutput("preview-rendered.json",MODE_PRIVATE)){marker.write(Core.utf(p.toString()));}return new JSONObject();}
  if(action.equals("state")){JSONObject value=publicState(true);MainActivity ui=screen.get();if(ui!=null&&ui.getIntent().hasExtra("widgetPage"))value.put("startPage",ui.getIntent().getStringExtra("widgetPage"));return value;}if(action.equals("runtime"))return publicState(false);
  if(preview){if(action.equals("achievements"))return new JSONObject().put("game",games.getJSONObject(1)).put("rows",new JSONArray().put(new JSONObject().put("id","1").put("name","First steps").put("lockedDescription","Complete the first mission.").put("pack","Base game").put("unavailable","").put("isUnlocked",false)));throw new Exception("Offline preview: network and account actions are disabled.");}
  switch(action){
   case "findTitles":{TitleSearch.SearchResult search=TitleSearch.searchResults(p.getString("query"));JSONArray matches=search.items;for(int i=0;i<matches.length();i++){JSONObject g=matches.getJSONObject(i);foundTitles.put(g.getString("titleId"),g);if(foundTitles.size()>512)foundTitles.remove(foundTitles.keySet().iterator().next());}return new JSONObject().put("results",matches).put("partial",search.partial);}
   case "refresh":refresh();return publicState(true);
   case "scan":launch(ScanActivity.class,20);return new JSONObject();
   case "login":launch(LoginActivity.class,21);return new JSONObject();
   case "open360":launch(Xbox360Activity.class,23);return new JSONObject();
   case "manual":replaceAccount(Net.connect(p.getString("authorization")));notice="Account connected.";refresh();return publicState(true);
   case "disconnect":if(queueGate.busy()||spoofGate.busy())throw new Exception("Stop sessions first.");save();account=null;eventTokenProbeStatus="";games=new JSONArray();queue=new JSONArray();pending=null;save();return publicState(true);
   case "testMobileEventToken":{
    if(!foreground||queueGate.busy()||spoofGate.busy())throw new Exception("Keep the app open and stop active sessions before this test.");
    synchronized(stateLock){
     if(account==null)throw new Exception("Sign in with Microsoft on this device first.");
     JSONObject before=new JSONObject(account.toString());String owner=before.getString("xuid");
     try{
      JSONObject next=MobileEventTokens.acquire(before,refresh->{if(account==null||!owner.equals(account.optString("xuid")))throw new Exception("Account changed.");account.put("refreshToken",refresh);save();},Build.VERSION.RELEASE,MobileEventTokens.LIVE);
      if(account==null||!owner.equals(account.optString("xuid")))throw new Exception("Account changed.");
      JSONObject retained=new JSONObject(account.toString());account=next;try{save();}catch(Exception failedSave){account=retained;throw failedSave;}eventTokenProbeStatus="Microsoft issued a matching event token; saved securely. No achievement events were sent. Collector acceptance is not tested.";
     }catch(MobileEventTokens.Failure e){eventTokenProbeStatus=e.getMessage();}
     catch(Exception e){eventTokenProbeStatus="Mobile event-token test could not complete. Existing event token retained. No achievement events were sent.";}
     notice=eventTokenProbeStatus;return publicState(true);
    }
   }
   case "saveToken":if(queueGate.busy())throw new Exception("Pause queue first.");auth();account.put("eventToken",Core.token(p.getString("token"),true));save();return publicState(true);
   case "clearToken":if(queueGate.busy())throw new Exception("Pause queue first.");auth();account.put("eventToken","");save();return publicState(true);
   case "confirmPC":{if(pending==null||pending.getLong("expiresAt")<=System.currentTimeMillis()/1000)throw new Exception("Transfer expired. Scan fresh codes.");boolean only=p.optBoolean("eventOnly");if(pending.optBoolean("eventOnly")&&!only)throw new Exception("This transfer contains only an event token.");if(only){if(pending.optBoolean("signInOnly"))throw new Exception("This QR contains sign-in only.");if(account==null||!account.getString("xuid").equals(pending.getString("xuid")))throw new Exception("Event import requires the same account.");account.put("eventToken",pending.getString("eventToken"));save();}else{JSONObject a=new JSONObject(pending.toString());a.remove("eventOnly");a.remove("expiresAt");replaceAccount(a);}pending=null;notice="PC sync complete.";if(!only&&prefs.optBoolean("autoRefresh",true))refresh();return publicState(true);}
   case "cancelPC":pending=null;return publicState(true);
   case "achievements":{JSONObject g=lookup(p.getString("title"));JSONArray r=rows(g,auth().getString("xuid"));boolean inLibrary=false;for(int i=0;i<games.length();i++)if(games.getJSONObject(i).getString("titleId").equals(g.getString("titleId")))inLibrary=true;if(!inLibrary)g=TitleSearch.progress(g,r);completion(g,r);return new JSONObject().put("game",g).put("rows",r);}
   case "importBackground":{main.post(()->{MainActivity ui=screen.get();if(ui!=null)ui.backgroundFile();});return new JSONObject();}
   case "lookup":{JSONObject g=lookup(p.getString("title"));Double minutes=Net.minutes(auth(),g.getString("titleId"));return new JSONObject().put("game",g).put("hours",minutes==null?JSONObject.NULL:minutes/60.0);}
   case "unlock":{if(queueGate.busy())throw new Exception("Pause Auto Unlock before sending selected achievements.");JSONObject g=lookup(p.getString("title"));JSONArray r=rows(g,auth().getString("xuid")),ids=p.getJSONArray("ids");ExecutorService batch=Executors.newFixedThreadPool(3);List<Future<String>> results=new ArrayList<>();Set<String> unique=new HashSet<>();try{for(int i=0;i<ids.length();i++){String id=ids.getString(i);if(!unique.add(id))continue;JSONObject row=selectRow(r,id);results.add(batch.submit(()->{try{send(g,row);return "";}catch(Exception e){return row.optString("name")+": request not confirmed — "+safe(e);}}));}List<String> errors=new ArrayList<>();for(Future<String> result:results){String error=result.get();if(!error.isEmpty())errors.add(error);}notice=errors.isEmpty()?"Sent "+results.size()+" actions together. Refresh to verify progress.":String.join("\n",errors)+"\nRefresh progress before retrying.";}finally{batch.shutdownNow();}return new JSONObject().put("message",notice);}
   case "addWidget":main.post(()->{MainActivity ui=screen.get();if(ui!=null)SessionWidget.pin(ui);});return new JSONObject();
   case "exportQueueQR":case "scanQueueQR":{if(queueGate.busy())throw new Exception("Pause Auto Unlock first.");auth();save();boolean exporting=action.equals("exportQueueQR");java.util.ArrayList<String> frames=exporting?QueueQR.frames(QueueTransfer.export(account.getString("xuid"),savedQueues),account.getString("xuid")):null;main.post(()->{MainActivity ui=screen.get();if(ui!=null)ui.queueQr(exporting,frames);});return new JSONObject();}
   case "exportQueues":transferFile(true);return new JSONObject();
   case "importEvents":if(queueGate.busy())throw new Exception("Pause Auto Unlock before importing event data.");main.post(()->{MainActivity ui=screen.get();if(ui!=null)ui.eventPackFile();});return new JSONObject();
   case "importQueues":transferFile(false);return new JSONObject();
   case "enqueue":{if(queueGate.busy())throw new Exception("Pause queue before editing.");JSONObject g=lookup(p.getString("title"));JSONArray incoming=new JSONArray();JSONArray own=rows(g,auth().getString("xuid")),ids=p.getJSONArray("ids");for(int i=0;i<ids.length();i++){JSONObject row=selectRow(own,ids.getString(i));if(!row.optString("unavailable").isEmpty()||unlocked(row))continue;boolean exists=false;for(int q=0;q<queue.length();q++)if(queue.getJSONObject(q).getJSONObject("game").getString("titleId").equals(g.getString("titleId"))&&queue.getJSONObject(q).getString("achievementId").equals(row.getString("id")))exists=true;if(!exists||p.optBoolean("separate"))incoming.put(new JSONObject().put("game",g).put("achievementId",row.getString("id")).put("name",row.getString("name")).put("description",row.optString("description",row.optString("lockedDescription"))).put("delay",Math.max(0,Math.min(31536000,row.optLong("_delay",prefs.optLong("delay",60))))).put("status","Waiting"));}acceptQueue(incoming,p.optBoolean("separate"),false);return publicState(true);}
   case "reference":{if(queueGate.busy())throw new Exception("Pause before building the queue.");JSONObject g=lookup(p.getString("title")),a=auth();String tag=p.getString("gamertag").trim();if(tag.isEmpty()||tag.length()>64)throw new Exception("Enter a gamertag.");JSONObject profile=Net.xbox("https://profile.xboxlive.com/users/gt("+Net.enc(tag)+")/profile/settings?settings=Gamertag",a.getString("authorization"),"2","GET",null).getJSONArray("profileUsers").getJSONObject(0);JSONArray other=rows(g,Core.numeric(profile.getString("id"))),own=rows(g,a.getString("xuid"));List<JSONObject> ordered=new ArrayList<>();for(int i=0;i<other.length();i++){JSONObject row=other.getJSONObject(i);if(!unlocked(row))continue;try{JSONObject fresh=selectRow(own,row.getString("id"));if(!fresh.optString("name").equalsIgnoreCase(row.optString("name"))||!fresh.optString("serviceConfigId").equals(row.optString("serviceConfigId"))||unlocked(fresh)||!fresh.optString("unavailable").isEmpty())continue;JSONObject progression=row.optJSONObject("progression");String stamp=progression==null?row.optString("timeUnlocked"):progression.optString("timeUnlocked");long time=Instant.parse(stamp).toEpochMilli();if(time<946684800000L)continue;ordered.add(new JSONObject().put("row",fresh).put("time",time));}catch(Exception ignored){}}ordered.sort(Comparator.comparingLong(x->x.optLong("time")));if(ordered.isEmpty())throw new Exception("No matching locked achievements with reference times. Queue retained.");long previous=0;JSONArray replacement=new JSONArray();for(JSONObject item:ordered){JSONObject row=item.getJSONObject("row");long time=item.getLong("time"),delay=previous==0?0:Math.max(0,Math.min(31536000,(time-previous)/1000));replacement.put(new JSONObject().put("game",g).put("achievementId",row.getString("id")).put("name",row.getString("name")).put("description",row.optString("description",row.optString("lockedDescription"))).put("delay",delay).put("status","Waiting"));previous=time;}acceptQueue(replacement,p.optBoolean("separate"),true);notice=p.optBoolean("separate")?"Reference queue saved separately.":"Reference queue loaded. Review delays before starting.";return publicState(true);}
   case "editQueue":{if(queueGate.busy())throw new Exception("Pause before editing.");int index=QueueLibrary.find(queue,p.getString("id"));if(index<0||index>=queue.length())throw new Exception("Queue item missing.");if(p.optBoolean("remove"))queue.remove(index);else if(p.has("status")){String status=p.getString("status");if(!status.equals("Waiting")&&!status.equals("Skipped by user"))throw new Exception("Invalid queue action.");queue.getJSONObject(index).put("status",status).remove("remainingDelay");}else {queue.getJSONObject(index).put("delay",Math.max(0,Math.min(31536000,p.getDouble("delay"))));queue.getJSONObject(index).remove("remainingDelay");}save();return publicState(true);}
   case "removeCompleted":{if(queueGate.busy())throw new Exception("Pause first.");JSONArray next=new JSONArray();Map<String,JSONArray> loaded=new HashMap<>();for(int i=0;i<queue.length();i++){JSONObject item=queue.getJSONObject(i),g=item.getJSONObject("game");String id=g.getString("titleId");if(!loaded.containsKey(id))loaded.put(id,rows(g,auth().getString("xuid")));if(!unlocked(selectRow(loaded.get(id),item.getString("achievementId"))))next.put(item);}queue=next;save();return publicState(true);}
   case "openGameSession":{
    auth();if(queueGate.busy()||spoofRunning)throw new Exception("Stop active sessions before changing games.");
    String title=Core.numeric(p.getString("title"));
    if(QueueLibrary.shouldRestore(savedQueues,queue,title,queueGate.busy()||spoofRunning)){
     JSONArray items=QueueLibrary.restore(savedQueues.getJSONObject(title));save();queue=items;previousQueue=new JSONArray();save();
     notice="Saved game loaded. Review and press Start when ready.";
    }
    return publicState(true);
   }
   case "loadGameQueue":{if(queueGate.busy())throw new Exception("Pause before loading a saved queue.");String title=Core.numeric(p.getString("title"));JSONArray items=QueueLibrary.restore(savedQueues.getJSONObject(title));save();if(!p.optBoolean("append")){queue=new JSONArray();previousQueue=new JSONArray();}queue=QueueLibrary.append(queue,items);save();notice="Saved game loaded. Review and press Start when ready.";return publicState(true);}
   case "confirmDeleteGameQueue":{
    if(queueGate.busy()||account==null)throw new Exception("Sign in and pause Auto Unlock first.");String title=Core.numeric(p.getString("title")),owner=account.getString("xuid"),name=savedQueues.getJSONObject(title).optString("name","Game");
    main.post(()->{MainActivity ui=screen.get();if(ui!=null)ui.confirmDeleteGameQueue(title,name,owner);});return new JSONObject();
   }
   case "deleteGameQueue":{
    if(queueGate.busy())throw new Exception("Pause Auto Unlock before deleting saved queues.");
    if(account==null||!account.getString("xuid").equals(p.getString("owner")))throw new Exception("The signed-in account changed. Choose the queue again.");String title=Core.numeric(p.getString("title"));
    if(!savedQueues.has(title))throw new Exception("Saved queue no longer exists.");save();
    JSONObject beforeSaved=new JSONObject(savedQueues.toString());JSONArray beforeQueue=QueueLibrary.copy(queue),beforePrevious=QueueLibrary.copy(previousQueue);
    try{queue=QueueLibrary.deleteGame(savedQueues,queue,title);previousQueue=QueueLibrary.copy(queue);save();}
    catch(Exception error){savedQueues=beforeSaved;queue=beforeQueue;previousQueue=beforePrevious;throw error;}
    notice="Saved game queue deleted, including its loaded items. Other games were retained.";return publicState(true);
   }
   case "saveQueue":save();return publicState(true);
   case "queueStart":startQueue();return publicState(true);
   case "queuePause":pause();keepAwake();return publicState(true);
   case "spoofStart":startSpoof(p.getString("title"));return publicState(true);
   case "spoofStop":stopSpoof();return publicState(true);
   case "prefs":prefs=p;if(!foreground&&!prefs.optBoolean("backgroundSessions",true)){pause();stopSpoof();}save();return publicState(true);
   case "notifications":requestNotifications();return new JSONObject();
   case "events":{JSONObject feed=new JSONObject(Net.read(EVENT_FEED,"GET",null,null,null,null,32*1024*1024));JSONObject before=catalogue.synced;try{int n=catalogue.merge(feed);save();notice="Event sync complete: "+n+" new titles. Existing mappings retained.";}catch(Exception e){catalogue.synced=before;throw e;}return publicState(true);}
   case "scanCompletion":{for(int i=0;i<games.length();i++){JSONObject g=games.getJSONObject(i);JSONArray r=rows(g,auth().getString("xuid"));completion(g,r);notice="Scanned "+(i+1)+" / "+games.length();push();if(!foreground)break;}return publicState(true);}
   case "updates":return Updater.check(this);
   case "installUpdate":return Updater.download(this);
   case "finishUpdate":if(queueGate.busy()||spoofGate.busy())throw new Exception("Pause sessions before installing an update.");main.post(()->{MainActivity ui=screen.get();if(ui!=null)Updater.install(ui);});return new JSONObject();
   case "openRelease":{String url=p.getString("url");if(!url.startsWith(Updater.REPOSITORY+"/releases/tag/"))throw new Exception("Invalid release link.");main.post(()->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(url)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)));return new JSONObject();}
   default:throw new Exception("Unknown app action.");
  }
 }

